import * as THREE from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  normalWorld,
  positionWorld,
  cameraPosition,
  vec3,
  saturate,
  dot,
  normalize,
  mix,
  uv,
  texture,
  Fn,
} from 'three/tsl';
import gsap from 'gsap';
import { NodeConfig, NodeContext } from '@/primitives';

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  // --- Load texture ---
  const mapTexture = ctx.textureLoader.load(config.imageUrl);
  mapTexture.needsUpdate = true;

  // --- Compute plane dimensions from atlas region (capsule label shape) ---
  const { sourceRect } = config.atlasRegion || { sourceRect: { x: 0, y: 0, w: 512, h: 320 } };
  const aspect = sourceRect.w / sourceRect.h;
  const baseWidth = 0.8;  // scene units
  const baseHeight = baseWidth / aspect;

  // --- Create plane geometry ---
  const geometry = new THREE.PlaneGeometry(baseWidth, baseHeight);

  // --- Define custom node material with accent edge rim light ---
  const material = new MeshBasicNodeMaterial({
    colorNode: Fn(() => {
      // Sample the base texture
      const baseColor = texture(mapTexture, uv());

      // Compute view direction in world space
      const viewDir = normalize(cameraPosition.sub(positionWorld));
      // Rim term: strong at grazing angles
      const rim = saturate(1.0 - dot(normalWorld, viewDir));

      // Accent color (signal red)
      const accentColor = vec3(0xff / 255, 0x2a / 255, 0x38 / 255); // #ff2a38

      // Combine: base + accent rim intensity (0.5 max)
      const finalColor = mix(baseColor, accentColor, rim.mul(0.5));

      return finalColor;
    })(),
    transparent: true,
    depthWrite: true,
  });

  // --- Create mesh ---
  const mesh = new THREE.Mesh(geometry, material);

  // --- Set transform from config ---
  const { scenePosition, rotation, scale } = config;
  if (scenePosition) {
    mesh.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  }
  if (rotation) {
    mesh.rotation.set(rotation.x, rotation.y, rotation.z);
  }
  if (scale) {
    mesh.scale.set(scale.x, scale.y, scale.z);
  }

  // --- Interactivity ---
  const riseUpAmount = 0.15; // scene units
  let tl = gsap.timeline({ paused: true });

  // Hover: subtle rise-in
  mesh.userData.handlers = {
    onPointerEnter: () => {
      gsap.to(mesh.position, {
        y: mesh.position.y + riseUpAmount,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    onPointerLeave: () => {
      gsap.to(mesh.position, {
        y: mesh.position.y - riseUpAmount,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    onClick: () => {
      // Emit navigation event: hub-pricing.select
      mesh.dispatchEvent(new CustomEvent('navigate', { detail: 'hub-pricing.select' }));
      // Press-down animation
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        yoyo: true,
        repeat: 1,
      });
    },
  };

  // Enable pointer events on mesh
  mesh.userData.interactive = true;

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
    mapTexture.dispose();
  };

  return mesh;
}
